def gen(rng):
    def fmt(n, edges):
        return f'{n} {len(edges)}\n' + '\n'.join(f'{u} {v} {w}' for u, v, w in edges)

    def connected(n, m, maxw):
        perm = list(range(1, n + 1))
        rng.shuffle(perm)
        es, seen = [], set()
        for v in range(2, n + 1):
            u = rng.randint(1, v - 1)
            a, b = perm[u - 1], perm[v - 1]
            seen.add((min(a, b), max(a, b)))
            es.append((a, b, rng.randint(1, maxw)))
        while len(es) < m:
            u, v = rng.randint(1, n), rng.randint(1, n)
            if u == v:
                continue
            key = (min(u, v), max(u, v))
            if key in seen:
                continue
            seen.add(key)
            es.append((u, v, rng.randint(1, maxw)))
        rng.shuffle(es)
        return es

    tests = [
        fmt(2, [(1, 2, 5)]),
        fmt(2, [(2, 1, 1)]),
        fmt(4, [(1, 2, 1), (1, 3, 2), (2, 4, 3), (3, 4, 1), (2, 3, 1)]),
        fmt(4, [(1, 2, 1), (1, 3, 1), (2, 4, 1), (3, 4, 1), (2, 3, 1)]),
        fmt(5, [(1, 2, 2), (2, 3, 2), (3, 4, 2), (4, 5, 2)]),
    ]
    for n in range(2, 9):
        for _ in range(4):
            mx = n * (n - 1) // 2
            m = rng.randint(n - 1, mx)
            tests.append(fmt(n, connected(n, m, rng.choice([1, 2, 5, 100]))))
    tests.append(fmt(300, connected(300, 40000, 3)))
    tests.append(fmt(20000, connected(20000, 40000, 10**5)))
    tests.append(fmt(20000, connected(20000, 40000, 2)))
    r, c = 100, 200
    es = []
