        for j in range(c):
            u = i * c + j + 1
            if j + 1 < c:
                es.append((u, u + 1, rng.randint(1, 3)))
            if i + 1 < r:
                es.append((u, u + c, rng.randint(1, 3)))
    tests.append(fmt(r * c, es))
    tests.append(fmt(20000, [(i, i + 1, rng.randint(1, 10**5)) for i in range(1, 20000)]))
